1	// contractlab —— 可热更新的本地接口场景服务
2	//
3	// 运行环境：Node.js 24（内置 TypeScript 类型擦除，可直接 `node app.ts`），
4	// 无任何外部运行依赖。
5	//
6	// 行为约定（详见 README.md）：
7	// - 业务接口由“方法 + 绝对路径”唯一标识，查询串不参与匹配，不支持路径模板；
8	// - 请求被完整接收后，才按当前配置匹配接口并同步“预留”响应序列的下一项，
9	//   序列耗尽后持续返回末项；预留之后客户端断开，仍计为一次消费；
10	// - POST /__contractlab/reload 重新读取同一配置文件：新配置全部有效时才
11	//   原子替换全部接口、重置全部序列并递增版本号；失败时现状不变；
12	// - 在途请求持有预留时的旧响应快照（状态码/响应头/正文/延迟/版本），
13	//   完成时不会推进新序列；
14	// - POST 接口可附加可选的 requestBody 正文结构规则：请求完整接收后先校验
15	//   媒体类型与 JSON 结构，不符时返回 400 差异报告，不发送场景响应、不消费序列；
16	//   校验通过才按“完整接收”顺序预留响应项。
17	// - compare 子命令：离线比较旧、新两份场景文件，判断沿用旧接口约定的客户端
18	//   是否仍能调用新版；报告写 stdout，不启动监听、不修改文件。
19	
20	import http from 'node:http';
21	import { readFile } from 'node:fs/promises';
22	import path from 'node:path';
23	
24	const APP_NAME = 'contractlab';
25	
26	// 管理入口（保留前缀，业务接口不得使用）
27	const ADMIN_PREFIX = '/__contractlab/';
28	const HEALTH_PATH = '/__contractlab/health';
29	const RELOAD_PATH = '/__contractlab/reload';
30	
31	// 每个业务响应都携带当前配置版本
32	const VERSION_HEADER = 'X-Contractlab-Version';
33	
34	// 请求体上限（本机工具的防误操作保护，超出直接 413，不触碰任何序列）
35	const MAX_BODY_BYTES = 100 * 1024 * 1024;
36	
37	// 由服务器管理、业务配置不得覆盖的“传输头”（大小写不敏感）
38	const BLOCKED_HEADERS = new Set([
39	  'connection',
40	  'keep-alive',
41	  'content-length',
42	  'transfer-encoding',
43	]);
44	
45	// RFC 7230 token：合法的 HTTP 头名称字符
46	const HEADER_NAME_RE = /^[!#$%&'*+\-.^_`|~0-9A-Za-z]+$/;
47	
48	type HttpMethod = 'GET' | 'POST';
49	
50	// ---------------------------------------------------------------------------
51	// 请求正文结构规则（endpoints[].requestBody，仅 POST）
52	// ---------------------------------------------------------------------------
53	//
54	// 规则格式（JSON 对象，未知字段一律拒绝）：
55	//   { "type": "object", "fields": { "<名>": <字段规则>, ... }, "additionalProperties": false }
56	//   { "type": "array", "items": <规则> }
57	//   { "type": "string" | "number" | "integer" | "boolean" | "null" }
58	// 字段规则 = 任意规则 + 可选 "required": true（缺省为可缺省）；
59	// object 的 fields / additionalProperties 可省略（默认无字段声明、拒绝未声明字段）；
60	// array 必须声明 items。
61	
62	type ScalarKind = 'string' | 'number' | 'integer' | 'boolean' | 'null';
63	
64	type BodyRule =
65	  | {
66	      readonly kind: 'object';
67	      readonly fields: ReadonlyMap<string, FieldRule>;
68	      readonly additionalProperties: boolean;
69	    }
70	  | { readonly kind: 'array'; readonly items: BodyRule }
71	  | { readonly kind: ScalarKind };
72	
73	interface FieldRule {
74	  readonly rule: BodyRule;
75	  readonly required: boolean;
76	}
77	
78	interface ResponseSpec {
79	  readonly status: number;
80	  readonly headers: { readonly [name: string]: string };
81	  readonly body: string;
82	  readonly delay: number;
83	}
84	
85	interface EndpointSpec {
86	  readonly method: HttpMethod;
87	  readonly path: string;
88	  readonly responses: readonly ResponseSpec[];
89	  readonly bodyRule: BodyRule | undefined;
90	}
91	
92	interface LiveEndpoint {
93	  readonly key: string;
94	  readonly responses: readonly ResponseSpec[];
95	  readonly bodyRule: BodyRule | undefined;
96	  // 下一个待预留位置；到达末项后停在末项（持续复用）
97	  cursor: number;
98	}
99	
100	interface LiveState {
101	  readonly version: number;
102	  readonly endpoints: ReadonlyMap<string, LiveEndpoint>;
103	}
104	
105	interface ReloadResult {
106	  ok: boolean;
107	  version: number;
108	  error?: string;
109	}
110	
111	class ConfigError extends Error {
112	  constructor(message: string) {
113	    super(message);
114	    this.name = 'ConfigError';
115	  }
116	}
117	
118	// ---------------------------------------------------------------------------
119	// 配置校验
120	// ---------------------------------------------------------------------------
121	
122	function isPlainObject(value: unknown): value is Record<string, unknown> {
123	  return typeof value === 'object' && value !== null && !Array.isArray(value);
124	}
125	
126	function validatePath(p: string, where: string): void {
127	  if (p.length === 0 || p[0] !== '/') {
128	    throw new ConfigError(`${where}.path 必须是以 "/" 开头的绝对路径，收到 "${p}"`);
129	  }
130	  if (p.length > 4096) {
131	    throw new ConfigError(`${where}.path 过长（最多 4096 字符）`);
132	  }
133	  for (const ch of p) {
134	    const code = ch.charCodeAt(0);
135	    if (ch === '?' || ch === '#' || ch === '{' || ch === '}') {
136	      throw new ConfigError(
137	        `${where}.path "${p}" 含有非法字符 "${ch}"：查询串不参与匹配，且不支持路径模板`,
138	      );
139	    }
140	    if (code <= 0x1f || code === 0x7f || code === 0x20) {
141	      throw new ConfigError(`${where}.path "${p}" 不得包含空白或控制字符`);
142	    }
143	  }
144	}
145	
146	function validateResponse(raw: unknown, where: string): ResponseSpec {
147	  if (!isPlainObject(raw)) {
148	    throw new ConfigError(`${where} 必须是对象`);
149	  }
150	  for (const key of Object.keys(raw)) {
151	    if (key !== 'status' && key !== 'headers' && key !== 'body' && key !== 'delay') {
152	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
153	    }
154	  }
155	
156	  const { status, headers, body, delay } = raw;
157	
158	  if (!Number.isInteger(status) || status < 200 || status > 599) {
159	    throw new ConfigError(`${where}.status 必须是 200 至 599 之间的整数，收到 ${JSON.stringify(status)}`);
160	  }
161	
162	  if (!isPlainObject(headers)) {
163	    throw new ConfigError(`${where}.headers 必须是字符串键值对象`);
164	  }
165	  // 无原型对象：名为 "__proto__" 的头也按自有字段保留，不被原型 setter 吞掉
166	  const cleanHeaders: { [name: string]: string } = Object.create(null);
167	  const seenNames = new Set<string>();
168	  for (const [name, value] of Object.entries(headers)) {
169	    const whereHeader = `${where}.headers["${name}"]`;
170	    if (!HEADER_NAME_RE.test(name)) {
171	      throw new ConfigError(`${whereHeader} 不是合法的 HTTP 响应头名称`);
172	    }
173	    const lower = name.toLowerCase();
174	    if (BLOCKED_HEADERS.has(lower)) {
175	      throw new ConfigError(`${whereHeader} 属于服务器管理的传输头，不允许在配置中设置`);
176	    }
177	    if (seenNames.has(lower)) {
178	      throw new ConfigError(`${whereHeader} 与同序列内另一个响应头仅大小写不同，视为重复`);
179	    }
180	    if (typeof value !== 'string') {
181	      throw new ConfigError(`${whereHeader} 的值必须是字符串`);
182	    }
183	    for (let i = 0; i < value.length; i += 1) {
184	      const code = value.charCodeAt(i);
185	      // 允许水平制表符(0x09)；拒绝换行及其余控制字符；
186	      // Node 的 HTTP 头值只支持 Latin-1（0x80-0xFF），更高码位发送时会抛错
187	      if ((code <= 0x1f && code !== 0x09) || code === 0x7f || code > 0xff) {
188	        throw new ConfigError(
189	          `${whereHeader} 的值不得包含换行或其他控制字符，且只能使用 Latin-1 字符`,
190	        );
191	      }
192	    }
193	    seenNames.add(lower);
194	    cleanHeaders[name] = value;
195	  }
196	
197	  if (typeof body !== 'string') {
198	    throw new ConfigError(`${where}.body 必须是文本字符串`);
199	  }
200	  if ((status === 204 || status === 304) && body !== '') {
201	    throw new ConfigError(`${where}.body 状态码为 ${status} 时正文必须为空字符串`);
202	  }
203	
204	  if (!Number.isInteger(delay) || delay < 0 || delay > 60000) {
205	    throw new ConfigError(`${where}.delay 必须是 0 至 60000 之间的整数毫秒数，收到 ${JSON.stringify(delay)}`);
206	  }
207	
208	  return { status, headers: cleanHeaders, body, delay };
209	}
210	
211	const SCALAR_KINDS: ReadonlySet<string> = new Set([
212	  'string',
213	  'number',
214	  'integer',
215	  'boolean',
216	  'null',
217	]);
218	
219	function validateBodyRule(raw: unknown, where: string): BodyRule {
220	  if (!isPlainObject(raw)) {
221	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
222	  }
223	
224	  const type = raw.type;
225	  const allowed = new Set(['type']);
226	  if (type === 'object') {
227	    allowed.add('fields');
228	    allowed.add('additionalProperties');
229	  } else if (type === 'array') {
230	    allowed.add('items');
231	  } else if (!SCALAR_KINDS.has(type as string)) {
232	    throw new ConfigError(
233	      `${where}.type 必须是 "object" | "array" | "string" | "number" | "integer" | "boolean" | "null"，收到 ${JSON.stringify(type)}`,
234	    );
235	  }
236	  for (const key of Object.keys(raw)) {
237	    if (!allowed.has(key)) {
238	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
239	    }
240	  }
241	
242	  if (type === 'object') {
243	    const fieldsRaw = raw.fields;
244	    const fields = new Map<string, FieldRule>();
245	    if (fieldsRaw !== undefined) {
246	      if (!isPlainObject(fieldsRaw)) {
247	        throw new ConfigError(`${where}.fields 必须是对象（字段名 → 字段规则）`);
248	      }
249	      for (const [name, fieldRaw] of Object.entries(fieldsRaw)) {
250	        fields.set(name, validateFieldRule(fieldRaw, `${where}.fields[${JSON.stringify(name)}]`));
251	      }
252	    }
253	    const additional = raw.additionalProperties;
254	    if (additional !== undefined && typeof additional !== 'boolean') {
255	      throw new ConfigError(`${where}.additionalProperties 必须是布尔值`);
256	    }
257	    // 未声明字段默认拒绝
258	    return { kind: 'object', fields, additionalProperties: additional === true };
259	  }
260	
261	  if (type === 'array') {
262	    if (raw.items === undefined) {
263	      throw new ConfigError(`${where}.items 数组规则必须声明元素规则`);
264	    }
265	    return { kind: 'array', items: validateBodyRule(raw.items, `${where}.items`) };
266	  }
267	
268	  return { kind: type as ScalarKind };
269	}
270	
271	// 字段规则 = 任意规则 + 可选 "required"（仅允许出现在 object 的 fields 条目中）
272	function validateFieldRule(raw: unknown, where: string): FieldRule {
273	  if (!isPlainObject(raw)) {
274	    throw new ConfigError(`${where} 必须是对象（含 "type" 字段）`);
275	  }
276	  let required = false;
277	  // 无原型对象：未知规则键 "__proto__" 必须作为自有字段保留下来，
278	  // 交由 validateBodyRule 拒绝；普通对象字面量会在复制时被原型 setter 吞掉
279	  const rest: Record<string, unknown> = Object.create(null);
280	  for (const [key, value] of Object.entries(raw)) {
281	    if (key === 'required') {
282	      if (typeof value !== 'boolean') {
283	        throw new ConfigError(`${where}.required 必须是布尔值`);
284	      }
285	      required = value;
286	    } else {
287	      rest[key] = value;
288	    }
289	  }
290	  return { rule: validateBodyRule(rest, where), required };
291	}
292	
293	function validateEndpoint(
294	  raw: unknown,
295	  index: number,
296	  seen: Set<string>,
297	): EndpointSpec {
298	  const where = `endpoints[${index}]`;
299	  if (!isPlainObject(raw)) {
300	    throw new ConfigError(`${where} 必须是对象`);
301	  }
302	  for (const key of Object.keys(raw)) {
303	    if (key !== 'method' && key !== 'path' && key !== 'responses' && key !== 'requestBody') {
304	      throw new ConfigError(`${where} 含未知字段 "${key}"`);
305	    }
306	  }
307	
308	  const { method, path: routePath, responses, requestBody } = raw;
309	
310	  if (method !== 'GET' && method !== 'POST') {
311	    throw new ConfigError(`${where}.method 必须是 "GET" 或 "POST"，收到 ${JSON.stringify(method)}`);
312	  }
313	
314	  if (typeof routePath !== 'string') {
315	    throw new ConfigError(`${where}.path 必须是字符串`);
316	  }
317	  validatePath(routePath, where);
318	  if (routePath === '/__contractlab' || routePath.startsWith(ADMIN_PREFIX)) {
319	    throw new ConfigError(
320	      `${where}.path "${routePath}" 与管理入口冲突：前缀 "${ADMIN_PREFIX}" 为管理接口保留`,
321	    );
322	  }
323	
324	  const key = `${method} ${routePath}`;
325	  if (seen.has(key)) {
326	    throw new ConfigError(`${where} 与其他接口重复（方法 + 路径必须唯一）：${key}`);
327	  }
328	  seen.add(key);
329	
330	  if (!Array.isArray(responses) || responses.length === 0) {
331	    throw new ConfigError(`${where}.responses 必须是非空数组`);
332	  }
333	  const cleanResponses = responses.map((item, j) =>
334	    validateResponse(item, `${where}.responses[${j}]`),
335	  );
336	
337	  let bodyRule: BodyRule | undefined;
338	  if (requestBody !== undefined) {
339	    if (method !== 'POST') {
340	      throw new ConfigError(`${where}.requestBody 仅允许在 POST 接口上声明（GET 接口不允许携带此规则）`);
341	    }
342	    bodyRule = validateBodyRule(requestBody, `${where}.requestBody`);
343	  }
344	
345	  return { method, path: routePath, responses: cleanResponses, bodyRule };
346	}
347	
348	function validateConfig(raw: unknown): EndpointSpec[] {
349	  if (!isPlainObject(raw)) {
350	    throw new ConfigError('配置顶层必须是 JSON 对象');
351	  }
352	  for (const key of Object.keys(raw)) {
353	    if (key !== 'endpoints') {
354	      throw new ConfigError(`未知顶层字段 "${key}"，仅允许 "endpoints"`);
355	    }
356	  }
357	  const list = raw.endpoints;
358	  if (!Array.isArray(list) || list.length === 0) {
359	    throw new ConfigError('endpoints 必须是至少包含一个接口的数组');
360	  }
361	  const seen = new Set<string>();
362	  return list.map((ep, i) => validateEndpoint(ep, i, seen));
363	}
364	
365	// ---------------------------------------------------------------------------
366	// 运行时状态：配置快照 + 每接口独立序列
367	// ---------------------------------------------------------------------------
368	
369	function buildState(version: number, specs: readonly EndpointSpec[]): LiveState {
370	  const endpoints = new Map<string, LiveEndpoint>();
371	  for (const spec of specs) {
372	    endpoints.set(`${spec.method} ${spec.path}`, {
373	      key: `${spec.method} ${spec.path}`,
374	      responses: spec.responses,
375	      bodyRule: spec.bodyRule,
376	      cursor: 0,
377	    });
378	  }
379	  return { version, endpoints };
380	}
381	
382	// 同步预留下一项；同一事件循环内按“完整接收”事件的先后串行调用，天然保序。
383	// 末项之后持续返回末项，不跳项、不复用未到位置的项。
384	function reserveNext(endpoint: LiveEndpoint): ResponseSpec {
385	  const last = endpoint.responses.length - 1;
386	  const position = endpoint.cursor < last ? endpoint.cursor : last;
387	  if (endpoint.cursor < last) {
388	    endpoint.cursor += 1;
389	  }
390	  return endpoint.responses[position];
391	}
392	
393	// ---------------------------------------------------------------------------
394	// 请求正文校验：媒体类型 → UTF-8 JSON 解析 → 结构比对
395	// ---------------------------------------------------------------------------
396	
397	interface StructureProblem {
398	  readonly pointer: string;
399	  readonly expected: string;
400	  readonly actual: string;
401	}
402	
403	interface BodyReport {
404	  readonly error: 'invalid_request_body';
405	  readonly stage: 'parse' | 'structure';
406	  readonly message: string;
407	  readonly problems: readonly StructureProblem[];
408	}
409	
410	function parseFailure(message: string): BodyReport {
411	  return { error: 'invalid_request_body', stage: 'parse', message, problems: [] };
412	}
413	
414	function jsonTypeOf(value: unknown): string {
415	  if (value === null) {
416	    return 'null';
417	  }
418	  if (Array.isArray(value)) {
419	    return 'array';
420	  }
421	  return typeof value;
422	}
423	
424	// RFC 6901 JSON Pointer 段转义：~ -> ~0，/ -> ~1
425	function escapePointerSegment(segment: string): string {
426	  return segment.replace(/~/g, '~0').replace(/\//g, '~1');
427	}
428	
429	// 结构比对：父节点类型不符时只报告该节点，不再深入制造子节点错误；
430	// 字段缺失（hasOwnProperty 为假）与合法的 JSON null 分开判断。
431	function checkRule(
432	  rule: BodyRule,
433	  value: unknown,
434	  pointer: string,
435	  problems: StructureProblem[],
436	): void {
437	  switch (rule.kind) {
438	    case 'string':
439	    case 'boolean':
440	      if (typeof value !== rule.kind) {
441	        problems.push({ pointer, expected: rule.kind, actual: jsonTypeOf(value) });
442	      }
443	      return;
444	    case 'null':
445	      if (value !== null) {
446	        problems.push({ pointer, expected: 'null', actual: jsonTypeOf(value) });
447	      }
448	      return;
449	    case 'number':
450	      if (typeof value !== 'number' || !Number.isFinite(value)) {
451	        problems.push({ pointer, expected: 'number', actual: jsonTypeOf(value) });
452	      }
453	      return;
454	    case 'integer':
455	      if (!Number.isInteger(value)) {
456	        problems.push({ pointer, expected: 'integer', actual: jsonTypeOf(value) });
457	      }
458	      return;
459	    case 'array': {
460	      if (!Array.isArray(value)) {
461	        problems.push({ pointer, expected: 'array', actual: jsonTypeOf(value) });
462	        return;
463	      }
464	      for (let i = 0; i < value.length; i += 1) {
465	        checkRule(rule.items, value[i], `${pointer}/${i}`, problems);
466	      }
467	      return;
468	    }
469	    case 'object': {
470	      if (!isPlainObject(value)) {
471	        problems.push({ pointer, expected: 'object', actual: jsonTypeOf(value) });
472	        return;
473	      }
474	      for (const [name, field] of rule.fields) {
475	        const childPointer = `${pointer}/${escapePointerSegment(name)}`;
476	        if (!Object.prototype.hasOwnProperty.call(value, name)) {
477	          if (field.required) {
478	            problems.push({
479	              pointer: childPointer,
480	              expected: `${field.rule.kind}（必填字段）`,
481	              actual: 'missing',
482	            });
483	          }
484	        } else {
485	          checkRule(field.rule, value[name], childPointer, problems);
486	        }
487	      }
488	      if (!rule.additionalProperties) {
489	        for (const key of Object.keys(value)) {
490	          if (!rule.fields.has(key)) {
491	            problems.push({
492	              pointer: `${pointer}/${escapePointerSegment(key)}`,
493	              expected: '未声明的字段（不允许）',
494	              actual: jsonTypeOf(value[key]),
495	            });
496	          }
497	        }
498	      }
499	      return;
500	    }
501	  }
502	}
503	
504	// 返回 null 表示校验通过；否则为可直接序列化的 400 差异报告
505	function validateRequestBody(
506	  req: http.IncomingMessage,
507	  body: Buffer,
508	  rule: BodyRule,
509	): BodyReport | null {
510	  const contentType = req.headers['content-type'];
511	  const mediaType =
512	    typeof contentType === 'string' ? contentType.split(';', 1)[0].trim().toLowerCase() : '';
513	  if (mediaType !== 'application/json') {
514	    return parseFailure(
515	      typeof contentType === 'string'
516	        ? `媒体类型不符：期望 application/json（可带参数、忽略大小写），收到 "${contentType}"`
517	        : '缺少 Content-Type 头：期望 application/json（可带参数、忽略大小写）',
518	    );
519	  }
520	
521	  if (body.length === 0) {
522	    return parseFailure('请求正文为空，无法解析为 JSON');
523	  }
524	
525	  let text: string;
526	  try {
527	    text = new TextDecoder('utf-8', { fatal: true }).decode(body);
528	  } catch {
529	    return parseFailure('请求正文不是合法的 UTF-8 编码');
530	  }
531	
532	  let parsed: unknown;
533	  try {
534	    parsed = JSON.parse(text);
535	  } catch (e) {
536	    return parseFailure(`请求正文不是合法 JSON：${describeError(e)}`);
537	  }
538	
539	  const problems: StructureProblem[] = [];
540	  checkRule(rule, parsed, '', problems);
541	  if (problems.length > 0) {
542	    return {
543	      error: 'invalid_request_body',
544	      stage: 'structure',
545	      message: `请求正文与接口约定存在 ${problems.length} 处差异`,
546	      problems,
547	    };
548	  }
549	  return null;
550	}
