991	function writeResponse(
992	  res: http.ServerResponse,
993	  status: number,
994	  headers: { readonly [name: string]: string },
995	  body: string,
996	): void {
997	  try {
998	    res.writeHead(status, headers);
999	    res.end(body === '' ? undefined : body);
1000	  } catch {
1001	    // 预留之后客户端可能已断开：响应仍计为已消费，发送失败仅静默忽略
1002	  }
1003	}
1004	
1005	function versionHeaders(
1006	  version: number,
1007	  extra?: { readonly [name: string]: string },
1008	): { [name: string]: string } {
1009	  // 无原型对象：配置中名为 "__proto__" 的响应头在合并时不丢失
1010	  const headers: { [name: string]: string } = Object.create(null);
1011	  headers[VERSION_HEADER] = String(version);
1012	  if (extra) {
1013	    for (const [name, value] of Object.entries(extra)) {
1014	      headers[name] = value;
1015	    }
1016	  }
1017	  return headers;
1018	}
1019	
1020	function sendJson(res: http.ServerResponse, status: number, value: unknown, version: number): void {
1021	  writeResponse(
1022	    res,
1023	    status,
1024	    versionHeaders(version, { 'Content-Type': 'application/json; charset=utf-8' }),
1025	    `${JSON.stringify(value)}\n`,
1026	  );
1027	}
1028	
1029	function sendNotFound(res: http.ServerResponse): void {
1030	  writeResponse(
1031	    res,
1032	    404,
1033	    versionHeaders(activeState.version, {
1034	      'Content-Type': 'text/plain; charset=utf-8',
1035	    }),
1036	    'not found\n',
1037	  );
1038	}
1039	
1040	function sendBusinessResponse(
1041	  res: http.ServerResponse,
1042	  item: ResponseSpec,
1043	  version: number,
1044	): void {
1045	  const headers = versionHeaders(version);
1046	  let contentTypeSet = false;
1047	  for (const [name, value] of Object.entries(item.headers)) {
1048	    const lower = name.toLowerCase();
1049	    // 版本头由服务器填写且必须唯一准确：配置中的同名头（含大小写变体）可加载，发送时忽略其值
1050	    if (lower === VERSION_HEADER.toLowerCase()) {
1051	      continue;
1052	    }
1053	    if (lower === 'content-type') {
1054	      contentTypeSet = true;
1055	    }
1056	    headers[name] = value;
1057	  }
1058	  // 文本正文的默认内容类型；配置显式给出时不覆盖
1059	  if (!contentTypeSet && item.body !== '') {
1060	    headers['Content-Type'] = 'text/plain; charset=utf-8';
1061	  }
1062	  writeResponse(res, item.status, headers, item.body);
1063	}
1064	
1065	// 延迟结束才发送；即便客户端提前断开也继续计时（消费在预留时已经成立）
1066	function scheduleBusinessResponse(
1067	  res: http.ServerResponse,
1068	  item: ResponseSpec,
1069	  version: number,
1070	): void {
1071	  const timer = setTimeout(() => {
1072	    pendingTimers.delete(timer);
1073	    sendBusinessResponse(res, item, version);
1074	  }, item.delay);
1075	  pendingTimers.add(timer);
1076	}
