1078	type BodyOutcome = 'received' | 'aborted' | 'too-large';
1079	
1080	interface ReceivedBody {
1081	  readonly outcome: BodyOutcome;
1082	  // 仅在 outcome 为 'received' 时有意义（完整请求体）
1083	  readonly body: Buffer;
1084	}
1085	
1086	// 完整接收请求体；未完整接收即断开返回 'aborted'（调用方不得推进序列）
1087	function receiveBody(req: http.IncomingMessage, res: http.ServerResponse): Promise<ReceivedBody> {
1088	  return new Promise((resolve) => {
1089	    let settled = false;
1090	    let size = 0;
1091	    const chunks: Buffer[] = [];
1092	    const finish = (outcome: BodyOutcome): void => {
1093	      if (!settled) {
1094	        settled = true;
1095	        resolve({ outcome, body: outcome === 'received' ? Buffer.concat(chunks) : Buffer.alloc(0) });
1096	      }
1097	    };
1098	    req.on('data', (chunk: Buffer) => {
1099	      size += chunk.byteLength;
1100	      if (size > MAX_BODY_BYTES) {
1101	        finish('too-large');
1102	        writeResponse(
1103	          res,
1104	          413,
1105	          versionHeaders(activeState.version, {
1106	            'Content-Type': 'text/plain; charset=utf-8',
1107	          }),
1108	          'payload too large\n',
1109	        );
1110	        // 等 413 刷出后再断开，避免客户端收不到响应
1111	        res.once('finish', () => req.socket.destroy());
1112	        return;
1113	      }
1114	      chunks.push(chunk);
1115	    });
1116	    req.on('end', () => finish('received'));
1117	    req.on('error', () => finish('aborted'));
1118	    req.on('aborted', () => finish('aborted'));
1119	    res.on('close', () => finish('aborted'));
1120	  });
1121	}
1122	
1123	async function dispatch(
1124	  req: http.IncomingMessage,
1125	  res: http.ServerResponse,
1126	): Promise<void> {
1127	  res.on('error', () => {
1128	    // 写已销毁套接字等错误无需让进程崩溃
1129	  });
1130	
1131	  const { outcome, body } = await receiveBody(req, res);
1132	  if (outcome !== 'received') {
1133	    // aborted：未完整接收，不匹配、不预留、不推进任何序列
1134	    // too-large：已回复 413
1135	    return;
1136	  }
1137	
1138	  const method = String(req.method);
1139	  const pathname = String(req.url ?? '/').split('?')[0]; // 查询串不参与匹配
1140	
1141	  // 管理入口（不消费任何业务序列）
1142	  if (pathname === HEALTH_PATH) {
1143	    if (method === 'GET') {
1144	      sendJson(res, 200, { status: 'ok', version: activeState.version }, activeState.version);
1145	    } else {
1146	      sendNotFound(res);
1147	    }
1148	    return;
1149	  }
1150	
1151	  if (pathname === RELOAD_PATH) {
1152	    if (method === 'POST') {
1153	      const result = await triggerReload();
1154	      sendJson(res, 200, result, result.version);
1155	    } else {
1156	      sendNotFound(res);
1157	    }
1158	    return;
1159	  }
1160	
1161	  // 业务匹配：在本次同步执行内抓取状态快照，预留后与后续 reload 互不影响
1162	  const state = activeState;
1163	  const endpoint =
1164	    method === 'GET' || method === 'POST'
1165	      ? state.endpoints.get(`${method} ${pathname}`)
1166	      : undefined;
1167	
1168	  if (!endpoint) {
1169	    sendNotFound(res); // 未匹配请求：404，不消费
1170	    return;
1171	  }
1172	
1173	  // 正文结构规则（如有）：校验失败返回 400 差异报告，不发送场景响应、不消费序列。
1174	  // 规则、序列与版本均取自上面同一快照 state。
1175	  if (endpoint.bodyRule) {
1176	    const report = validateRequestBody(req, body, endpoint.bodyRule);
1177	    if (report) {
1178	      sendJson(res, 400, report, state.version);
1179	      return;
1180	    }
1181	  }
1182	
1183	  const item = reserveNext(endpoint); // 校验通过后立即预留
1184	  scheduleBusinessResponse(res, item, state.version);
1185	}
1186	
1187	// ---------------------------------------------------------------------------
1188	// 启动、信号处理
1189	// ---------------------------------------------------------------------------
1190	
1191	function shutdown(): void {
1192	  if (shuttingDown) {
1193	    return;
1194	  }
1195	  shuttingDown = true;
1196	  // 取消所有尚未发出的延迟响应
1197	  for (const timer of pendingTimers) {
1198	    clearTimeout(timer);
1199	  }
1200	  pendingTimers.clear();
1201	  // 关闭监听并断开空闲/在途连接，随后正常退出（退出码 0）
1202	  try {
1203	    server.closeAllConnections();
1204	  } catch {
1205	    // 旧版本兜底：忽略，下面的 close/超时仍会结束进程
1206	  }
1207	  server.close(() => process.exit(0));
1208	  setTimeout(() => process.exit(0), 2000).unref();
1209	}
1210	
1211	async function startServer(configArg: string, port: number): Promise<void> {
1212	  configFile = path.resolve(configArg);
1213	
1214	  // 先读配置：配置无效时根本不会创建监听
1215	  activeState = await loadStateFromFile(configFile, 1);
1216	
1217	  server = http.createServer((req, res) => {
1218	    dispatch(req, res).catch(() => {
1219	      try {
1220	        req.socket.destroy();
1221	      } catch {
1222	        // 套接字可能已销毁
1223	      }
1224	    });
1225	  });
1226	
1227	  await new Promise<void>((resolve, reject) => {
1228	    server.once('error', reject);
1229	    // 仅监听本机回环地址
1230	    server.listen(port, '127.0.0.1', resolve);
1231	  });
1232	
1233	  const address = server.address();
1234	  const actualPort = typeof address === 'object' && address ? address.port : port;
1235	  process.stdout.write(
1236	    `${APP_NAME}: listening on http://127.0.0.1:${actualPort}\n` +
1237	      `${APP_NAME}: config ${configFile} (version 1, ${activeState.endpoints.size} endpoints)\n`,
1238	  );
1239	
1240	  const onSignal = (): void => shutdown();
1241	  process.on('SIGINT', onSignal);
1242	  process.on('SIGTERM', onSignal);
1243	}
