1294	function parseServeArgv(argv: readonly string[]): ServeOptions {
1295	  let config: string | undefined;
1296	  let port: number | undefined;
1297	
1298	  const readValue = (flag: string, inline: string | undefined, index: number): [string, number] => {
1299	    if (inline !== undefined) {
1300	      return [inline, index];
1301	    }
1302	    const value = argv[index + 1];
1303	    if (value === undefined) {
