1314	    }
1315	
1316	    let flag = token;
1317	    let inline: string | undefined;
1318	    const eq = token.indexOf('=');
1319	    if (eq >= 0) {
1320	      flag = token.slice(0, eq);
1321	      inline = token.slice(eq + 1);
1322	    }
1323	
1324	    if (flag === '--config' || flag === '-c') {
1325	      [config, i] = readValue(flag, inline, i);
1326	    } else if (flag === '--port' || flag === '-p') {
1327	      let value: string;
